CREATE TABLE IF NOT EXISTS business_units (id UUID PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, role TEXT NOT NULL, business_unit TEXT, status TEXT NOT NULL DEFAULT 'Active', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS chemicals (id UUID PRIMARY KEY, name TEXT NOT NULL, cas_number TEXT, molecular_formula TEXT, molecular_mass NUMERIC, supplier TEXT, business_units TEXT[] NOT NULL DEFAULT '{}', quantity NUMERIC, unit TEXT, location TEXT, hazards TEXT[] NOT NULL DEFAULT '{}', risk_level TEXT NOT NULL, exposure_routes TEXT[] NOT NULL DEFAULT '{}', sds_url TEXT, oels JSONB NOT NULL DEFAULT '{}', biological_monitoring TEXT[] NOT NULL DEFAULT '{}', exam_frequency_months INTEGER, review_status TEXT NOT NULL DEFAULT 'Draft', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ingestion_jobs (id UUID PRIMARY KEY, source TEXT NOT NULL, status TEXT NOT NULL, rows_received INTEGER NOT NULL DEFAULT 0, rows_imported INTEGER NOT NULL DEFAULT 0, errors JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workflows (id UUID PRIMARY KEY, type TEXT NOT NULL, subject_id TEXT NOT NULL, assignee TEXT, status TEXT NOT NULL, steps JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id UUID PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
